INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('0a8ddf62-fe6c-4902-98f6-3d7f15538bcf','TCF','22222222-0000-0000-0000-000000000001',NULL,'36ac02fa-0576-4237-8ca7-f641149bdde4','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour pose le sujet (la piscine), le second précise la durée d''inscription puis pose la question implicite « à quelle fréquence ? », qui porte sur **le rythme, la régularité**. Seule A « deux fois par semaine » exprime une fréquence. B exprime une **durée d''une séance** (« combien de temps restes-tu ? »). C exprime un **lieu** (« où se trouve la piscine ? »). D exprime un **but** (« pourquoi y vas-tu ? »). Piège B1 : A et B mélangent souvent dans l''oreille des candidats, car les deux donnent une indication temporelle.','true','2026-05-31 16:49:34.402744+02','2026-05-31 16:49:34.402744+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('1540861c-4a04-4e8e-a7c9-0fd963aee223','TCF','22222222-0000-0000-0000-000000000001',NULL,'8baec140-a67d-4ac7-9213-d3a66ccc17d3','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Les deux premiers tours fixent le contexte (lecture du roman terminée), le troisième pose la question implicite « tu en as pensé quoi ? », qui demande **une opinion, un jugement de valeur**. Seule C « beaucoup de bien » exprime une appréciation. A donne un **lieu de lecture** (« où l''as-tu lu ? »). B donne une **durée de lecture** (« en combien de temps l''as-tu lu ? »). D donne un **moment / contexte de lecture** (« quand le lisais-tu ? »). Piège B1 : trois distracteurs parlent de la lecture mais aucun ne livre un avis.','true','2026-05-31 16:49:32.566385+02','2026-05-31 16:49:32.566385+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('1a05fb59-dbab-4263-98a5-d1e9b8132543','TCF','22222222-0000-0000-0000-000000000001',NULL,'4eae4795-2772-4830-b958-07348ca9a151','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu me recommanderais quel restaurant ? » appelle **le nom / la désignation d''un restaurant**. Seule B « le petit italien au coin de la rue » identifie un établissement. A donne **le prix moyen**. C donne **la localisation**. D donne **l''heure conseillée**.','true','2026-05-31 16:50:42.202357+02','2026-05-31 16:50:42.202357+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('1c93e7a5-5213-4656-b456-7c68e8ff1d56','TCF','22222222-0000-0000-0000-000000000001',NULL,'ecf25678-09dd-40e2-9ee1-20ad8b3f623a','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Qui habite juste en face de toi ? » porte sur **l''identité / la composition du foyer voisin**. Seule A « une famille avec deux jeunes enfants » désigne les occupants. B donne **l''étage** (« où ? »). C donne **depuis quand**. D donne **le loyer** (« combien ? »).','true','2026-05-31 16:50:50.90162+02','2026-05-31 16:50:50.90162+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('2a066bb4-774f-4dc9-8f8c-fe4fe25028e2','TCF','22222222-0000-0000-0000-000000000001',NULL,'3fec2966-96d3-435b-bb31-5e3addf91138','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour pose le contexte (le retour d''Italie de l''interlocutrice) ; le second contient la question implicite « combien de temps ? », qui porte sur **la durée d''un séjour passé**. Seule A « trois semaines » exprime une durée. B donne le **lieu / les villes visitées** (« où es-tu allé ? »). C donne l''**accompagnant** (« avec qui ? »). D donne le **but du voyage** (« pourquoi y es-tu allé ? »). Piège B1 : A contient « l''été dernier » qui ressemble à un moment, mais la durée principale est bien « trois semaines ».','true','2026-05-31 16:49:30.651368+02','2026-05-31 16:49:30.651368+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('3b3553d8-7869-4d35-a7d1-e1de6e8f855a','TCF','22222222-0000-0000-0000-000000000001',NULL,'bf27b420-860c-4bd7-9cf3-4e5782c92e8f','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Les deux premiers tours fixent le contexte (les courses sont déjà faites). La question implicite « combien de bouteilles ? » porte sur **un nombre**. Seule B « six » donne une quantité. A renvoie au **type de vin** (« quel vin ? »). C renvoie au **prix total** (« combien as-tu dépensé ? »). D renvoie au **lieu d''achat** (« où les as-tu achetées ? ») — piège B1 : le contexte mentionne le supermarché, mais le caviste reste plausible. Seul B répond bien à « combien ».','true','2026-05-31 16:49:30.133108+02','2026-05-31 16:49:30.133108+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('3ced560d-0998-40a1-9f3c-e5f56f158ed5','TCF','22222222-0000-0000-0000-000000000001',NULL,'a4bb4653-eea7-43bd-9389-e1f7bd0c2eba','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« À quelle heure exactement ? » porte sur **l''heure précise du rendez-vous**. Seule A « à seize heures trente » donne une heure. B donne **le motif de la consultation**. C donne **le lieu** du cabinet. D donne **l''interlocuteur médical**.','true','2026-05-31 16:50:28.351642+02','2026-05-31 16:50:28.351642+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('4d176b98-5d1b-4114-b59f-bd0254e22e00','TCF','22222222-0000-0000-0000-000000000001',NULL,'42fba0eb-2b3c-48d7-83ce-dc8be8eb086e','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour mentionne le concert ; le second pose la question implicite « avec qui ? », qui porte sur **l''accompagnant**. Seule B « avec ma sœur et son copain » désigne des personnes. A donne le **lieu** (« où était-ce ? »). C donne un **moment / fin** (« jusqu''à quelle heure ? »). D donne la **cause** (« pourquoi y es-tu allé ? »). Toutes restent dans le champ « concert », ce qui en fait des distracteurs réalistes pour B1.','true','2026-05-31 16:49:33.209838+02','2026-05-31 16:49:33.209838+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('53e49fd8-12ab-4a43-bdcd-65e0d21ce92b','TCF','22222222-0000-0000-0000-000000000001',NULL,'4e593d6a-88ac-40f2-8045-9539bd9cdc3c','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« C''est prévu pour quelle date ? » porte sur **la date du rendez-vous**. Seule C « le quinze du mois prochain » donne une date. A donne **le poste visé**. B donne **le lieu de l''entretien**. D donne **les interlocuteurs**.','true','2026-05-31 16:50:51.484838+02','2026-05-31 16:50:51.484838+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('5afaf94b-1764-4388-9b06-3174692d36ff','TCF','22222222-0000-0000-0000-000000000001',NULL,'6d4e80c5-1ac8-4c93-9554-4d2993095d7a','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Quel style, plutôt ? » porte sur **le genre musical écouté**. Seule D « du jazz instrumental » désigne un style. A donne **le matériel utilisé** (« avec quoi écoutes-tu ? »). B donne **la durée d''écoute**. C donne **le but** (« pourquoi en écoutes-tu ? »).','true','2026-05-31 16:50:31.250992+02','2026-05-31 16:50:31.250992+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('5c2506b4-432a-4101-b074-3a8b09157044','TCF','22222222-0000-0000-0000-000000000001',NULL,'5d0b528c-9282-4639-8e14-8c3d7ab7cbf1','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le contexte (hésitation entre deux paires, demande d''avis) prépare une question de **choix entre deux options proposées**. La question implicite « tu préfères laquelle ? » appelle l''identification d''une des deux. Seule A « la noire, sans hésiter » désigne un choix. B donne un **lieu d''achat possible** (« où en trouver ? »). C donne un **prix** (« combien coûtent-elles ? »). D donne un **usage** (« pour quoi faire ? »). Piège B1 : B, C, D restent crédibles dans une conversation sur des chaussures, mais aucune ne répond à « laquelle ».','true','2026-05-31 16:49:33.754454+02','2026-05-31 16:49:33.754454+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('61ab0fd2-5b46-4878-92c4-d2538a89535b','TCF','22222222-0000-0000-0000-000000000001',NULL,'70fc56b1-4569-4b04-b834-49540d8437db','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','La question porte sur **la couleur du vélo**. Seule B « bleu foncé avec des liserés blancs » donne une couleur. A donne **le type de vélo** (« quel type ? »). C donne **l''usage** (« pour quoi faire ? »). D donne **le lieu d''achat** (« où l''as-tu acheté ? »).','true','2026-05-31 16:50:33.585889+02','2026-05-31 16:50:33.585889+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('755c75e2-0fd0-43ea-ae9d-6ff2b1a971a9','TCF','22222222-0000-0000-0000-000000000001',NULL,'61484468-fabf-4458-82a0-f7b0d84fac6c','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Il fait quoi dans la vie ? » porte sur **la profession du voisin**. Seule B « architecte dans une petite agence » nomme un métier. A donne **depuis quand il habite là**. C donne **son étage**. D donne **sa composition familiale**.','true','2026-05-31 16:50:48.151853+02','2026-05-31 16:50:48.151853+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('785101e5-ee79-4b42-ab51-e90e51fe5bdd','TCF','22222222-0000-0000-0000-000000000001',NULL,'ca839640-2c55-433f-8cdf-efd52a7c559e','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','La question retournée « et toi, tu fais quoi ? » porte sur **les activités prévues**. Seule D « du rangement et un peu de lecture » liste des activités. A donne **une cause / motif** (« pourquoi sortir ? »). B donne **l''accompagnante**. C donne **le but général** (« pour quoi faire ? »).','true','2026-05-31 16:50:50.267873+02','2026-05-31 16:50:50.267873+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('7f35bda8-7335-4e3d-9617-f5af86e27a05','TCF','22222222-0000-0000-0000-000000000001',NULL,'db38be0d-cb81-40a8-876d-d55acbf69438','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Les deux premiers tours installent l''étonnement (Léa pleure alors qu''elle est calme d''habitude), le troisième pose la question implicite « pourquoi ? », qui porte sur **la cause, ce qui a déclenché les pleurs**. Seule B « à cause d''une dispute » donne une cause antérieure. A donne une **durée** (« combien de temps a-t-elle pleuré ? »). C donne un **but** (« dans quel objectif pleurait-elle ? ») — piège B1 classique : confusion cause / but. D donne un **lieu** (« où était-elle ? »).','true','2026-05-31 16:49:31.418403+02','2026-05-31 16:49:31.418403+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('89080e14-2417-4817-9ea1-1f8ef672a28a','TCF','22222222-0000-0000-0000-000000000001',NULL,'8c18e1d7-bf1b-46e2-ac14-0ad24dce220b','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu es libre quand ? » porte sur **un créneau de disponibilité**. Seule C « mercredi après-midi » donne un créneau précis. A donne **un but / motif**. B donne **un accompagnement potentiel**. D donne **un lieu**.','true','2026-05-31 16:50:49.669129+02','2026-05-31 16:50:49.669129+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('8947412f-28d4-43a1-be85-613bab08d3e3','TCF','22222222-0000-0000-0000-000000000001',NULL,'0949c588-3e50-47fb-a44b-eea2fa798cc6','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Qu''est-ce qui t''a le plus surprise ? » porte sur **l''élément qui a marqué / étonné**. Seule C « le calme absolu de la nuit » désigne un tel élément. A donne **la durée du séjour**. B donne **les accompagnants**. D donne **le lieu**.','true','2026-05-31 16:50:32.317871+02','2026-05-31 16:50:32.317871+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('8f66f807-8c94-441f-bec3-e8e784a8b2e3','TCF','22222222-0000-0000-0000-000000000001',NULL,'341e223d-e390-4cac-b063-33cc7f097130','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Vous étiez combien ? » porte sur **le nombre de convives**. Seule B « une douzaine » donne un nombre. A donne **la qualité du repas** (« comment était le menu ? »). C donne **l''heure de fin** (« jusqu''à quand ? »). D donne **le lieu** (« où dîniez-vous ? »).','true','2026-05-31 16:50:30.784501+02','2026-05-31 16:50:30.784501+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('a00bc929-8047-4039-bcf7-8e9deebb454c','TCF','22222222-0000-0000-0000-000000000001',NULL,'f3c50fc2-2bb1-4e90-9f91-d090f2419ac4','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Vous avez eu quel temps ? » porte sur **la météo** pendant le séjour. Seule D « du soleil presque tout le séjour » décrit le temps. A donne **les accompagnants**. B donne **la période** du séjour. C donne **le lieu précis**.','true','2026-05-31 16:50:49.101405+02','2026-05-31 16:50:49.101405+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('b2e3ce65-34d3-4d15-98f2-c815dbd6b9cc','TCF','22222222-0000-0000-0000-000000000001',NULL,'fc71a32c-394f-44d2-82c6-a986cf56068b','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu y vas comment, en général ? » porte sur **le moyen de transport habituel**. Seule D « en train, puis à pied » nomme les moyens utilisés. A donne **l''heure de départ**. B donne **la durée du trajet**. C donne **une cause expliquant un autre choix** (« pourquoi pas en voiture ? »).','true','2026-05-31 16:50:30.251748+02','2026-05-31 16:50:30.251748+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('b46f6d55-581a-42ae-bfa6-d6067c78366c','TCF','22222222-0000-0000-0000-000000000001',NULL,'a217288b-2738-4ba8-bc3c-9cfd49fd9223','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Ça t''a coûté combien en tout ? » porte sur **le prix total payé**. Seule A « près de quatre cents euros » donne un montant. B donne **la durée de l''intervention**. C donne **les prestations incluses**. D donne **le lieu / la qualité du garage**.','true','2026-05-31 16:50:41.671065+02','2026-05-31 16:50:41.671065+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('bd5ca8f4-887b-4900-9a48-194106dc87c4','TCF','22222222-0000-0000-0000-000000000001',NULL,'4b62d51d-ddaf-4899-a7b8-895342ee640e','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu as préparé quoi ? » porte sur **le plat cuisiné**. Seule C « un tajine d''agneau aux pruneaux » nomme un plat. A donne **la durée** passée en cuisine. B donne **le nombre de convives**. D donne **l''aide reçue** (« avec qui as-tu cuisiné ? »).','true','2026-05-31 16:50:29.169233+02','2026-05-31 16:50:29.169233+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('c69d7d67-dc6d-4583-bfbf-f1c99bf3cbff','TCF','22222222-0000-0000-0000-000000000001',NULL,'8b41ec26-fc24-4fd2-abbb-f142ae82dbdd','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour fixe le sujet (une robe pour un mariage déjà trouvée) ; le second pose la question implicite « tu l''as dénichée où ? », qui porte sur **le lieu d''achat**. Seule D « dans une petite boutique du centre-ville » désigne un lieu. A donne un **accompagnant et un moment** (« avec qui et quand ? »). B donne une **description** de la robe (« comment est-elle ? »). C donne un **prix** (« combien l''as-tu payée ? »). Toutes les pistes restent crédibles dans un échange sur les achats.','true','2026-05-31 16:49:32.037718+02','2026-05-31 16:49:32.037718+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('d02724c3-3e95-4eab-bd0c-6f2a1ef45b2f','TCF','22222222-0000-0000-0000-000000000001',NULL,'3fb10d17-2d34-40e1-a449-02a775e96cc3','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','La question « tu parles de quoi ? » demande **l''identification de l''objet** désigné par « ça ». Seule C « le grand bol bleu » nomme un objet. A donne le **lieu** où il se trouve. B donne le **but** de la demande. D donne un **accessoire** qui l''accompagne.','true','2026-05-31 16:50:32.997331+02','2026-05-31 16:50:32.997331+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('d4e9bc58-428b-4391-b57a-1e8718839be3','TCF','22222222-0000-0000-0000-000000000001',NULL,'44c895f2-40e6-4dee-9c8f-e443517e8d3e','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu as préféré quoi, dans tout ce qu''elle a servi ? » porte sur **le plat favori du repas**. Seule D « le tiramisu fait maison » désigne un plat. A donne **le nombre d''invités**. B donne **la durée de la soirée**. C donne **les autres convives**.','true','2026-05-31 16:50:47.118255+02','2026-05-31 16:50:47.118255+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('dd0e791e-4d66-4d94-9a9d-227c52d09759','TCF','22222222-0000-0000-0000-000000000001',NULL,'71d9023c-1673-4c7f-80b7-a7a633f23d81','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu lui as offert quoi ? » porte sur **la nature de l''objet offert**. Seule B « une jolie raquette de tennis » nomme un cadeau. A donne **l''occasion** (« pour quel motif ? »). C donne **le lieu d''achat**. D donne **l''accompagnement et le moment** de l''achat.','true','2026-05-31 16:50:31.700891+02','2026-05-31 16:50:31.700891+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('e3cb5a63-3db5-4dd2-b6d2-68e828d7f197','TCF','22222222-0000-0000-0000-000000000001',NULL,'4071f7a9-34a3-4745-94bc-1d1185545893','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« C''est à quelle distance ? » porte sur **la distance géographique**. Seule A « à environ trois cent cinquante kilomètres » donne une distance. B donne **la fréquence des visites**. C donne **le moyen de transport**. D donne **le but / l''occasion**.','true','2026-05-31 16:50:52.836936+02','2026-05-31 16:50:52.836936+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('efffcc31-a8ff-4f4e-82f9-a77d5c6c03c0','TCF','22222222-0000-0000-0000-000000000001',NULL,'39a110a2-17db-43f1-aad6-8a278b69768c','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Les deux premiers tours plantent le contexte (le montage est terminé). La question finale « tu as fait comment ? » porte sur **la manière, la méthode employée**. Seule B « en suivant la notice étape par étape » (gérondif de moyen) y répond. A indique une **durée** (« combien de temps cela t''a-t-il pris ? »). C indique une **cause / motivation** (« pourquoi l''as-tu montée ? »). D indique un **lieu** (« où l''as-tu installée ? »). Piège B1 : les quatre réponses parlent bien du montage, seule la nature de la question (« comment ») permet de trancher.','true','2026-05-31 16:49:29.201727+02','2026-05-31 16:49:29.201727+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f8279fe6-8161-4db6-a012-faeb450fbd90','TCF','22222222-0000-0000-0000-000000000001',NULL,'0ed06acc-8f74-4198-b87a-f2507db73159','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour pose le sujet (un rendez-vous à la préfecture, déjà confirmé) ; le second contient la question implicite « pour quand exactement ? » qui porte sur **un moment précis**. Seule C « mercredi prochain, à dix heures » donne un point dans le temps. A indique un **lieu** dans la préfecture (« à quel guichet ? »). B exprime un **but / motif** (« pour quoi faire ? »). D précise l''**accompagnant** (« avec qui y vas-tu ? »). Toutes les réponses restent dans le champ administratif, ce qui rend le piège B1 réaliste.','true','2026-05-31 16:49:29.716948+02','2026-05-31 16:49:29.716948+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f8a4caec-7329-4a7e-86c5-be12b2d578ec','TCF','22222222-0000-0000-0000-000000000001',NULL,'dd02714e-f01c-4d47-b9df-843503246dc1','B1','CO','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu as ressenti quoi ? » porte sur **l''émotion personnelle** éprouvée. Seule A « une vraie fierté pour lui » nomme un sentiment. B donne **la cause de la promotion** du frère (« pourquoi a-t-il été promu ? »). C donne **la durée de l''appel**. D donne **l''accompagnante**.','true','2026-05-31 16:50:29.718214+02','2026-05-31 16:50:29.718214+02','ACTIVE',NULL,NULL,'co_dialogue_b1_implicite');
